example:
#include <iostream>
#include <stdexcept>
double divSafe(double a, double b) {
    if (b == 0) throw std::invalid_argument("Mau so bang 0");
    return a / b;
}
int main() {
    try { std::cout << divSafe(5, 0); }
    catch (const std::exception& e) { std::cout << "Bat loi: " << e.what() << '\n'; }
}

